local KTool = CS.Engine.Lib.KTool
local XLuaUtils = CS.Engine.Lib.XLuaUtils
local ImageAlterable = CS.Engine.UI.ImageAlterable
local UIEventProxy = CS.Engine.UI.UIEventProxy
local UIModule = CS.Engine.UI.UIModule
------------ import ------------

------------ define ------------
local TeamCellNodeLuaPath = 'Game.UI.TrailStage.TrailRankTeamCellNode'
local PlayerHeadNodePath = "Game.Behaviours.CommonPlayerHeadNode"

local cardConfMgr = CardConfMgr:GetInstance()
------------ define ------------


---@class TrailRankCellNode
---@field TeamItemCellNode                UnityEngine.RectTransform
---@field TeamNode                        UnityEngine.RectTransform
---@field ScoreText                        UnityEngine.UI.Text
---@field PlayerLevelText                UnityEngine.UI.Text
---@field HeadIcon                        UnityEngine.RectTransform
---@field NameText                        UnityEngine.UI.Text
---@field StateIcon                        UnityEngine.RectTransform
---@field MyLevel                        UnityEngine.RectTransform
---@field SeqNoText                        UnityEngine.UI.Text
---@field FirtLvImg                        UnityEngine.RectTransform
---@field Container                        UnityEngine.UI.Image  @用来改背景图色彩的
---@field HeadNode                        UnityEngine.UI.Image  @头像的点击跳转事件
local TrailRankCellNode = Class('TrailRankCellNode')

local COLORS = {
    '#d8c411', '#bbaf41', '#77713d'
}

function TrailRankCellNode:__init()
    self.dojo = nil
end

function TrailRankCellNode:__delete()
    self.dojo = nil
end

function TrailRankCellNode:Awake()
    UIEventProxy.Create(self.Container.gameObject).onPointerClick = function(event)
        ---点击事件
        if table.count(self.dojo.team) > 0 then
            UIModule.OpenDialog({id = Constants.UITypeIds.UITrailStageTeamPreviewDialog, parameters = {dojo = self.dojo}})
        end
    end

end

---FreshUI
---@param seqNo number
---@param dojo table
---@param isMy boolean
function TrailRankCellNode:FreshUI(seqNo, dojo, isMy, isAllRank)
    self.SeqNoText.text = seqNo
    self.dojo = dojo
    local playerHeadNode = GetLuaBehaviour(self.HeadIcon.gameObject, PlayerHeadNodePath)
    if not KTool.IsNull(playerHeadNode) and not isNull(playerHeadNode.Env) then
        ---@type CommonPlayerHeadNode
        local env = playerHeadNode.Env
        env:SetCallBack(function ()
            ---头像的点击跳转事件
            if checkInt(self.dojo.playerId) <= 0 then
                GameUtils.Toast(localize('该玩家暂未设置个人信息'))
            else
                GameUtils.ShowPlayerInfo(self.dojo.playerId, {
                    { id = Constants.UITypeIds.UITrailStageHome},
                    { id = Constants.UITypeIds.UITrailStageRankDialog},
                })
            end
        end)
        env:FreshAvatarFrame(dojo.avatar, dojo.avatarFrame)
    end
    isAllRank = checkBool(isAllRank)
    if isAllRank then
        KTool.SetActive(self.FirtLvImg.gameObject, seqNo <= 3)
        if seqNo <= 3 then
            KTool.GetOrAddComponent(self.FirtLvImg.gameObject, typeof(ImageAlterable)):LoadSprite(string.format('uiatlas/trailstage/competition_rank_label_no_%d.png', seqNo))
            self.Container.color = XLuaUtils.HexToColor(COLORS[seqNo])
        else
            self.Container.color = XLuaUtils.HexToColor('#727272')
        end
    else
        KTool.SetActive(self.FirtLvImg.gameObject, false)
        self.Container.color = XLuaUtils.HexToColor('#727272')
    end
    KTool.SetActive(self.MyLevel.gameObject, isMy)
    if isMy then
        self.Container.color = XLuaUtils.HexToColor('#ffaf0e')
    end
    self.NameText.text = dojo.name
    self.PlayerLevelText.text = tostring(dojo.level)
    self.ScoreText.text = tostring(math.floor(checkNumber(dojo.score)))
    local transform  = self.TeamNode.transform
    local childLen = transform.childCount
    if childLen ~= 3 then
        KTool.DestroyGameObjectChildren(self.TeamNode.gameObject, true)
        childLen = 0
    end
    if table.count(checkTable(dojo.team)) > 0 then
        local keys = sortByKey(dojo.team)
        for i, questId in pairs(keys) do
            local questDojo = dojo.team[tostring(questId)]
            local randIndex = 1
            --local randIndex = math.random(1, #checkTable(questDojo.cards))
            local go = nil
            if childLen == 0 then
                go = KTool.Instantiate(self.TeamNode.gameObject, self.TeamItemCellNode.gameObject)
            else
                local child = transform:GetChild(i - 1)
                if child then
                    go = child.gameObject
                end
            end
            if not isNull(go) then
                KTool.SetActive(go, true)
                local mb = GetLuaBehaviour(go, TeamCellNodeLuaPath)
                if mb then
                    if isNull(mb.Env) then
                        mb:Init()
                    end
                    ---@type TrailRankTeamCellNode
                    local env = mb.Env
                    local cardVo = cardConfMgr:GetCardByRefId(questDojo.cards[randIndex].cardId)
                    if isTable(cardVo) then
                        env:FreshUI(cardVo, math.floor(questDojo.score), i)
                    end
                end
            end
        end
        if #keys < childLen then
            for i = #keys + 1, childLen do
                local child = transform:GetChild(i - 1)
                if child then
                    KTool.SetActive(child.gameObject, false)
                end
            end
        end
    else
        KTool.DestroyGameObjectChildren(self.TeamNode.gameObject, true)
        KTool.SetActive(self.TeamItemCellNode.gameObject, false)
    end
end

function TrailRankCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return TrailRankCellNode